INSERT INTO historical_trades (id, date, season_era, title, description, trade_tree_description, team_a, team_b, initial_perspective, historical_outcome) VALUES ('tkachuk-huberdeau-2022', 'July 22, 2022', 'Salary Cap Era (2020s)', 'The Matthew Tkachuk Blockbuster', 'Florida lands superstar Matthew Tkachuk in exchange for 115-point winger Jonathan Huberdeau, MacKenzie Weegar, Cole Schwindt, and a 2025 1st round pick.', 'A seismic late-summer blockbuster that altered the trajectory of two franchises, ultimately delivering Florida its first Stanley Cup.', '{"teamName":"Florida Panthers","teamAbbrev":"FLA","teamLogo":"https://assets.nhle.com/logos/nhl/svg/FLA_light.svg","gaveUp":["Jonathan Huberdeau","MacKenzie Weegar","Cole Schwindt","2025 Conditional 1st Round Pick"],"received":["Matthew Tkachuk","Conditional 2025 4th Round Pick"],"snapshotGrade":"B+","retrospectiveGrade":"A+"}', '{"teamName":"Calgary Flames","teamAbbrev":"CGY","teamLogo":"https://assets.nhle.com/logos/nhl/svg/CGY_light.svg","gaveUp":["Matthew Tkachuk","Conditional 2025 4th Round Pick"],"received":["Jonathan Huberdeau","MacKenzie Weegar","Cole Schwindt","2025 Conditional 1st Round Pick"],"snapshotGrade":"A","retrospectiveGrade":"D"}', '{"narrative":"Tkachuk informed Calgary he would not sign a long-term extension. Flames GM Brad Treliving pulled off what many analysts called a masterclass: recovering an elite 115-point playmaker (Huberdeau) and a top-pairing defenseman (Weegar) plus a future 1st round pick.","teamAOutlook":"Florida sacrificed the franchise''s all-time assist leader and a premier blueliner to inject mean playoff grit and prime superstar swagger alongside Barkov.","teamBOutlook":"Calgary believed they dodged a catastrophic rebuild after losing Gaudreau to free agency, re-signing Huberdeau (8x$10.5M) and Weegar (8x$6.25M) to stay in immediate contention.","consensusVerdictAtTime":"Flames hailed for turning an impossible trade request into a haul. Panthers criticized for giving up too much depth.","cupOddsDeltaTeamA":"+14% (Shifted from fringe contender to elite core)","cupOddsDeltaTeamB":"+6% (Avoided total roster collapse)","players":[{"name":"Matthew Tkachuk","team":"FLA","ageAtTrade":24,"seasonPriorStats":"82 GP | 42 G | 62 A | 104 PTS | +57","contractStatus":"Signed 8-year, $76M ($9.5M AAV) extension upon trade","perceivedValue":"Top-5 power winger in the NHL entering his physical prime."},{"name":"Jonathan Huberdeau","team":"CGY","ageAtTrade":29,"seasonPriorStats":"80 GP | 30 G | 85 A | 115 PTS | +35","contractStatus":"1 year left at $5.9M, signed 8-year $84M ($10.5M AAV) extension","perceivedValue":"Reigning NHL assist leader and elite franchise playmaker."},{"name":"MacKenzie Weegar","team":"CGY","ageAtTrade":28,"seasonPriorStats":"80 GP | 8 G | 36 A | 44 PTS | +40","contractStatus":"1 year left at $3.25M, signed 8-year $50M ($6.25M AAV) extension","perceivedValue":"Premier 5v5 defensive defenseman with top-pairing analytics."}]}', '{"verdictToday":"One of the most decisive, franchise-defining wins in NHL history for Florida. Tkachuk became the heartbeat of Florida''s back-to-back Finals appearances and 2024 Stanley Cup championship, while Calgary entered a painful franchise rebuild.","lopsidednessRating":"ALL_TIME_FLEECING","winningTeam":"Florida Panthers","teamASuccessSummary":"2023 Stanley Cup Final appearance, 2024 Stanley Cup Champions, Tkachuk scored 109 and 88 points in regular seasons, scored clutch OT goals.","teamBSuccessSummary":"Missed playoffs back-to-back seasons. Huberdeau suffered the largest single-season scoring drop-off in NHL history (115 to 55 points). Flames traded away Lindholm, Hanifin, Markstrom, and Tanev.","championshipImpact":"Florida won the 2024 Stanley Cup with Tkachuk serving as playoff talisman.","milestones":[{"year":"2023","title":"Eastern Conference Champions","description":"Tkachuk scores 4 game-winning goals, including 3 OT winners, leading Florida from the 8th seed to the 2023 Stanley Cup Final.","tag":"CHAMPIONSHIP"},{"year":"2023","title":"Huberdeau Historical Scoring Drop","description":"Huberdeau finishes year 1 in Calgary with 55 points—a 60-point drop from his 115-point campaign in Florida.","tag":"COLLAPSE"},{"year":"2024","title":"Florida Hoists the 2024 Stanley Cup","description":"Panthers defeat Edmonton in 7 games to claim their first championship in franchise history.","tag":"CHAMPIONSHIP"}],"tradeTreeEvents":[{"team":"CGY","year":"2023-2024","event":"Flames Core Fire Sale","details":"With Huberdeau struggling and team missing playoffs, Calgary trades Lindholm, Hanifin, and Tanev for draft picks.","result":"Calgary officially enters full rebuild."},{"team":"CGY","year":"2025","event":"Florida 1st Round Pick","details":"Calgary retains Florida''s conditional 2025 1st round pick, expected to land late in round 1.","result":"Future prospect yet to be drafted."}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, historical_outcome=excluded.historical_outcome;
INSERT INTO historical_trades (id, date, season_era, title, description, trade_tree_description, team_a, team_b, initial_perspective, historical_outcome) VALUES ('roy-avalanche-1995', 'December 6, 1995', 'Dead Puck Era (1990s)', 'The Patrick Roy Cataclysm', 'Montreal Canadiens trade 2x Conn Smythe winner Patrick Roy and captain Mike Keane to Colorado Avalanche for Jocelyn Thibault, Martin Rucinsky, and Andrei Kovalenko.', 'Spurred by a personal rift with head coach Mario Tremblay, Montreal traded the greatest playoff goaltender in hockey history, instantly building an Avalanche dynasty.', '{"teamName":"Colorado Avalanche","teamAbbrev":"COL","teamLogo":"https://assets.nhle.com/logos/nhl/svg/COL_light.svg","gaveUp":["Jocelyn Thibault","Martin Rucinsky","Andrei Kovalenko"],"received":["Patrick Roy","Mike Keane"],"snapshotGrade":"A+","retrospectiveGrade":"A+"}', '{"teamName":"Montreal Canadiens","teamAbbrev":"MTL","teamLogo":"https://assets.nhle.com/logos/nhl/svg/MTL_light.svg","gaveUp":["Patrick Roy","Mike Keane"],"received":["Jocelyn Thibault","Martin Rucinsky","Andrei Kovalenko"],"snapshotGrade":"C-","retrospectiveGrade":"F"}', '{"narrative":"On Dec 2, 1995, Tremblay left Roy in net for 9 goals against Detroit. As he was pulled, Roy stormed past Tremblay and declared to team president Ronald Corey: \"This is my last game in Montreal.\" Four days later, he was gone.","teamAOutlook":"Colorado already had Joe Sakic and Peter Forsberg. Adding Roy gave them the ultimate Conn Smythe backstop.","teamBOutlook":"Montreal panicked under the media spotlight, accepting young goalie Thibault and two forwards without engaging in a broader bidding war.","consensusVerdictAtTime":"Montreal forced into a trade; Colorado crowned instant Stanley Cup favorites.","cupOddsDeltaTeamA":"+45% (Catapulted to #1 Cup contender)","cupOddsDeltaTeamB":"-38% (Ended 1993 championship era)","players":[{"name":"Patrick Roy","team":"COL","ageAtTrade":30,"seasonPriorStats":"22 GP | 12-9-1 | 2.95 GAA | .907 SV%","contractStatus":"Veteran superstar in his prime","perceivedValue":"Arguably the most clutch playoff goaltender of all time."},{"name":"Jocelyn Thibault","team":"MTL","ageAtTrade":20,"seasonPriorStats":"10 GP | 3-4-2 | 3.01 GAA | .874 SV%","contractStatus":"Former #10 overall draft pick","perceivedValue":"High-pedigree goalie prospect expected to succeed Roy."}]}', '{"verdictToday":"Universally regarded as one of the worst trades in sports history for Montreal, and the single transaction that created the Colorado Avalanche dynasty.","lopsidednessRating":"ALL_TIME_FLEECING","winningTeam":"Colorado Avalanche","teamASuccessSummary":"Won 1996 Stanley Cup six months later, won 2001 Stanley Cup, Roy won 2001 Conn Smythe and broke all-time goalie win records.","teamBSuccessSummary":"Montreal didn''t win a single Stanley Cup for the next 30+ years and entered a prolonged goaltending crisis until Carey Price arrived.","championshipImpact":"2 Stanley Cups (1996, 2001) for Colorado.","milestones":[{"year":"1996","title":"Avalanche Win 1996 Stanley Cup","description":"Roy sweeps the Florida Panthers in the 1996 Stanley Cup Final just 6 months after arriving in Denver.","tag":"CHAMPIONSHIP"},{"year":"2001","title":"Second Stanley Cup & Conn Smythe","description":"Roy carries Colorado past New Jersey in 7 games to win his 3rd career Conn Smythe and 4th Stanley Cup.","tag":"CHAMPIONSHIP"}],"tradeTreeEvents":[{"team":"MTL","year":"1998","event":"Thibault Traded to Chicago","details":"Montreal deals Thibault to Chicago along with Dave Manson for Jeff Hackett.","result":"Montreal fails to secure long-term franchise goalie."}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, historical_outcome=excluded.historical_outcome;
INSERT INTO historical_trades (id, date, season_era, title, description, trade_tree_description, team_a, team_b, initial_perspective, historical_outcome) VALUES ('eichel-vegas-2021', 'November 4, 2021', 'Salary Cap Era (2020s)', 'The Jack Eichel Blockbuster', 'Buffalo Sabres trade captain Jack Eichel and a 2023 3rd to Vegas Golden Knights for Alex Tuch, Peyton Krebs, a 2022 1st (Noah Östlund), and 2023 2nd.', 'A bitter neck injury standoff between Eichel and the Sabres concluded with Vegas acquiring a true franchise #1 center, leading directly to the 2023 Stanley Cup.', '{"teamName":"Vegas Golden Knights","teamAbbrev":"VGK","teamLogo":"https://assets.nhle.com/logos/nhl/svg/VGK_light.svg","gaveUp":["Alex Tuch","Peyton Krebs","2022 1st Round Pick (Noah Östlund)","2023 2nd Round Pick"],"received":["Jack Eichel","2023 3rd Round Pick"],"snapshotGrade":"A-","retrospectiveGrade":"A+"}', '{"teamName":"Buffalo Sabres","teamAbbrev":"BUF","teamLogo":"https://assets.nhle.com/logos/nhl/svg/BUF_light.svg","gaveUp":["Jack Eichel","2023 3rd Round Pick"],"received":["Alex Tuch","Peyton Krebs","2022 1st Round Pick (Noah Östlund)","2023 2nd Round Pick"],"snapshotGrade":"B+","retrospectiveGrade":"B"}', '{"narrative":"Eichel suffered a herniated disc in March 2021 and wanted artificial disc replacement surgery, which the Sabres medical staff refused to authorize. Stripped of the captaincy, Eichel sat out until Vegas took on his $10M cap hit and approved the surgery.","teamAOutlook":"Vegas risked significant cap space and an unprecedented surgery to finally secure the elite #1 center they lacked since inception.","teamBOutlook":"Buffalo embraced a cultural reset around youth, adding Syracuse native Alex Tuch, top prospect Peyton Krebs, and valuable draft capital.","consensusVerdictAtTime":"Win-win trade on paper with high medical risk assumed by Vegas.","cupOddsDeltaTeamA":"+20% (High upside if surgery succeeded)","cupOddsDeltaTeamB":"-5% (Short-term reset for future youth wave)","players":[{"name":"Jack Eichel","team":"VGK","ageAtTrade":25,"seasonPriorStats":"21 GP | 2 G | 16 A | 18 PTS (Injured)","contractStatus":"5 years remaining at $10.0M AAV","perceivedValue":"Franchise #1 center when healthy."},{"name":"Alex Tuch","team":"BUF","ageAtTrade":25,"seasonPriorStats":"55 GP | 18 G | 15 A | 33 PTS","contractStatus":"4 years remaining at $4.75M AAV","perceivedValue":"Dynamic top-6 power winger on team-friendly deal."}]}', '{"verdictToday":"Vegas gained the #1 center that powered their 2023 championship. Buffalo obtained an exceptional leader in Tuch (who blossomed into a 36-goal scorer), making it a competitive trade, but Vegas won the ultimate prize.","lopsidednessRating":"DECISIVE_WIN","winningTeam":"Vegas Golden Knights","teamASuccessSummary":"Eichel led the 2023 Stanley Cup Playoffs in scoring with 26 points in 22 games, winning Vegas its first Cup.","teamBSuccessSummary":"Tuch became the heartbeat of Buffalo with back-to-back 30+ goal paces, but Sabres playoff drought continued.","championshipImpact":"2023 Stanley Cup Champions (Vegas Golden Knights).","milestones":[{"year":"2021","title":"Historic Artificial Disc Surgery","description":"Eichel undergoes successful artificial disc replacement surgery, becoming the first NHL player to do so.","tag":"MILESTONE"},{"year":"2023","title":"2023 Stanley Cup Playoff Scoring Leader","description":"Eichel scores 26 points in 22 games to capture the 2023 Stanley Cup.","tag":"CHAMPIONSHIP"}],"tradeTreeEvents":[{"team":"BUF","year":"2022","event":"Drafting Noah Östlund","details":"Buffalo uses Vegas'' 1st round pick (16th overall) to select Swedish center Noah Östlund.","result":"Promising prospect developed in SHL/AHL."}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, historical_outcome=excluded.historical_outcome;
INSERT INTO historical_trades (id, date, season_era, title, description, trade_tree_description, team_a, team_b, initial_perspective, historical_outcome) VALUES ('karlsson-sharks-2018', 'September 13, 2018', 'Salary Cap Era (2010s)', 'The Erik Karlsson & Tim Stützle Trade', 'Ottawa Senators trade 2x Norris Trophy winner Erik Karlsson to San Jose Sharks for Josh Norris, Rudolfs Balcers, Chris Tierney, Dylan DeMelo, a 2020 1st (Tim Stützle), and 2019 2nd.', 'A seemingly lopsided blockbuster for San Jose flipped completely when the Sharks collapsed in 2020, gifting Ottawa the #3 overall pick used to draft franchise cornerstone Tim Stützle.', '{"teamName":"Ottawa Senators","teamAbbrev":"OTT","teamLogo":"https://assets.nhle.com/logos/nhl/svg/OTT_light.svg","gaveUp":["Erik Karlsson","Francis Perron"],"received":["Josh Norris","Rudolfs Balcers","Chris Tierney","Dylan DeMelo","2020 1st (Tim Stützle)","2019 2nd (Jamieson Rees)"],"snapshotGrade":"D+","retrospectiveGrade":"A+"}', '{"teamName":"San Jose Sharks","teamAbbrev":"SJS","teamLogo":"https://assets.nhle.com/logos/nhl/svg/SJS_light.svg","gaveUp":["Josh Norris","Rudolfs Balcers","Chris Tierney","Dylan DeMelo","2020 1st Round Pick","2019 2nd Round Pick"],"received":["Erik Karlsson","Francis Perron"],"snapshotGrade":"A","retrospectiveGrade":"D-"}', '{"narrative":"Ottawa was mired in dressing-room turmoil and ownership disputes. GM Pierre Dorion traded the franchise icon for roster depth and picks, incurring widespread ridicule from fans and media.","teamAOutlook":"Ottawa seemed to have given away an all-time great defenseman for spare parts.","teamBOutlook":"San Jose paired Karlsson with Brent Burns, creating an unmatched offensive blue line aiming for the 2019 Cup.","consensusVerdictAtTime":"Massive landslide victory for San Jose; disaster for Ottawa.","cupOddsDeltaTeamA":"-28% (Signaled painful bottom-out)","cupOddsDeltaTeamB":"+32% (Instant Cup favorite in Western Conference)","players":[{"name":"Erik Karlsson","team":"SJS","ageAtTrade":28,"seasonPriorStats":"71 GP | 9 G | 53 A | 62 PTS","contractStatus":"1 year remaining, later signed 8-year $92M ($11.5M AAV) extension","perceivedValue":"Generational offensive defenseman in his prime."},{"name":"Josh Norris","team":"OTT","ageAtTrade":19,"seasonPriorStats":"NCAA (Michigan): 37 GP | 9 G | 14 A | 23 PTS","contractStatus":"Unsigned 1st round prospect","perceivedValue":"Solid middle-six forward prospect."}]}', '{"verdictToday":"San Jose lost the 2019 Western Conference Final and crashed to the bottom of the NHL. Ottawa cashed the unprotected 2020 1st round pick into Tim Stützle (#3 overall), who became an 90-point superstar and face of the franchise.","lopsidednessRating":"ALL_TIME_FLEECING","winningTeam":"Ottawa Senators","teamASuccessSummary":"Drafted Tim Stützle (#3 in 2020); Josh Norris scored 35 goals in 2022; acquired foundation of young offensive core.","teamBSuccessSummary":"Reached 2019 WCF but signed Karlsson to $11.5M AAV cap-straining deal; team missed playoffs 5 consecutive years; traded Karlsson to Pittsburgh in 2023.","championshipImpact":"Neither team won the Cup, but Ottawa acquired their franchise star while San Jose entered a 5+ year rebuild.","milestones":[{"year":"2020","title":"Sens Draft Tim Stützle #3 Overall","description":"The Sharks'' unprotected 1st rounder wins #3 lottery spot, yielding elite German center Tim Stützle.","tag":"TRADE_TREE"},{"year":"2023","title":"Karlsson Rebounds, Wins 3rd Norris","description":"Karlsson posts historic 101-point season in SJ before being traded to Pittsburgh.","tag":"AWARD"}],"tradeTreeEvents":[{"team":"OTT","year":"2020","event":"The Stützle Pick","details":"Ottawa selects Tim Stützle with San Jose''s pick.","result":"Stützle signs 8-year $66.8M extension, scoring 90 points at age 21."},{"team":"SJS","year":"2023","event":"Karlsson Traded to Pittsburgh","details":"Sharks trade Karlsson to Penguins to shed cap space for Mikael Granlund and a 2024 1st.","result":"San Jose bottoms out to draft Macklin Celebrini #1 overall in 2024."}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, historical_outcome=excluded.historical_outcome;
INSERT INTO historical_trades (id, date, season_era, title, description, trade_tree_description, team_a, team_b, initial_perspective, historical_outcome) VALUES ('forsberg-erat-2013', 'April 3, 2013', 'Salary Cap Era (2010s)', 'The Filip Forsberg for Martin Erat Fleecing', 'Washington Capitals trade top prospect Filip Forsberg to Nashville Predators for Martin Erat and Michael Latta at the trade deadline.', 'Widely cited as the most lopsided trade-deadline panic in modern NHL history. Washington traded a future 300-goal sniper for a declining veteran who scored 2 goals in DC.', '{"teamName":"Nashville Predators","teamAbbrev":"NSH","teamLogo":"https://assets.nhle.com/logos/nhl/svg/NSH_light.svg","gaveUp":["Martin Erat","Michael Latta"],"received":["Filip Forsberg"],"snapshotGrade":"A","retrospectiveGrade":"A+"}', '{"teamName":"Washington Capitals","teamAbbrev":"WSH","teamLogo":"https://assets.nhle.com/logos/nhl/svg/WSH_light.svg","gaveUp":["Filip Forsberg"],"received":["Martin Erat","Michael Latta"],"snapshotGrade":"C","retrospectiveGrade":"F"}', '{"narrative":"Washington GM George McPhee wanted established veteran scoring and playoff grit for the 2013 stretch run. He parted with Forsberg (selected 11th overall in 2012), who had not yet played an NHL game.","teamAOutlook":"Nashville GM David Poile couldn''t believe Washington offered Forsberg for an aging, disgruntled Erat.","teamBOutlook":"Capitals hoped Erat would solidify their second line behind Ovechkin and Backstrom.","consensusVerdictAtTime":"Capitals paid a steep premium in future talent for immediate playoff reinforcement.","cupOddsDeltaTeamA":"+0% (Future-building move)","cupOddsDeltaTeamB":"+3% (Short-term win-now nudge)","players":[{"name":"Filip Forsberg","team":"NSH","ageAtTrade":18,"seasonPriorStats":"Sweden: 38 GP | 15 G | 18 A | 33 PTS","contractStatus":"Entry-Level Contract","perceivedValue":"Blue-chip sniper prospect."},{"name":"Martin Erat","team":"WSH","ageAtTrade":31,"seasonPriorStats":"36 GP | 4 G | 17 A | 21 PTS","contractStatus":"2 years remaining at $4.5M AAV","perceivedValue":"Consistent 50-point veteran two-way winger."}]}', '{"verdictToday":"One of the most catastrophic single-player trades in NHL history. Erat scored just 2 goals in 62 games for Washington, while Forsberg became Nashville''s all-time greatest forward.","lopsidednessRating":"ALL_TIME_FLEECING","winningTeam":"Nashville Predators","teamASuccessSummary":"Forsberg scored 300+ goals, 600+ points, broke the franchise single-season goal record (48 goals in 2024), and led Nashville to the 2017 Stanley Cup Final.","teamBSuccessSummary":"Erat requested a trade within 8 months after being demoted to the 4th line, scoring just 2 total goals before being dumped to Phoenix.","championshipImpact":"Nashville reached the 2017 Stanley Cup Final with Forsberg leading the charge.","milestones":[{"year":"2014","title":"Erat Dumped to Phoenix","description":"After scoring 2 goals in 62 games, Washington trades Erat to Phoenix for Chris Brown and Rostislav Klesla.","tag":"COLLAPSE"},{"year":"2017","title":"Predators Reach 2017 Stanley Cup Final","description":"Forsberg leads Nashville with 9 playoff goals and 16 points on their historic run to Game 6 of the Finals.","tag":"CHAMPIONSHIP"},{"year":"2024","title":"Forsberg Sets Franchise Goal Record","description":"Forsberg scores 48 goals and 94 points in 2023-24, cementing his legendary status in Nashville.","tag":"MILESTONE"}],"tradeTreeEvents":[{"team":"WSH","year":"2014","event":"Erat Flipped to Coyotes","details":"Washington trades Erat and John Mitchell for Chris Brown, Rostislav Klesla, and a 4th round pick.","result":"Zero lasting impact on Capitals roster."}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, historical_outcome=excluded.historical_outcome;
INSERT INTO historical_trades (id, date, season_era, title, description, trade_tree_description, team_a, team_b, initial_perspective, historical_outcome) VALUES ('gretzky-kings-1988', 'August 9, 1988', '80s Dynasty Era', 'The Great One: "The Trade"', 'Edmonton Oilers trade Wayne Gretzky, Marty McSorley, and Mike Krushelnyski to Los Angeles Kings for Jimmy Carson, Martin Gelinas, $15M USD, and three 1st round draft picks.', 'The trade that shook Canada to its core and forever changed the landscape of the NHL, igniting hockey''s expansion across the Sun Belt.', '{"teamName":"Los Angeles Kings","teamAbbrev":"LAK","teamLogo":"https://assets.nhle.com/logos/nhl/svg/LAK_light.svg","gaveUp":["Jimmy Carson","Martin Gelinas","$15 Million USD Cash","1989 1st","1991 1st","1993 1st"],"received":["Wayne Gretzky","Marty McSorley","Mike Krushelnyski"],"snapshotGrade":"A+","retrospectiveGrade":"A+"}', '{"teamName":"Edmonton Oilers","teamAbbrev":"EDM","teamLogo":"https://assets.nhle.com/logos/nhl/svg/EDM_light.svg","gaveUp":["Wayne Gretzky","Marty McSorley","Mike Krushelnyski"],"received":["Jimmy Carson","Martin Gelinas","$15 Million USD Cash","1989 1st","1991 1st","1993 1st"],"snapshotGrade":"C","retrospectiveGrade":"B-"}', '{"narrative":"Oilers owner Peter Pocklington was facing severe business debt and Gretzky was entering the final year of his contract. Pocklington orchestrated the sale of the greatest player in history for $15 million cash and future assets.","teamAOutlook":"Kings owner Bruce McNall instantly made hockey the hottest ticket in Hollywood, drawing celebrities and establishing hockey in southern California.","teamBOutlook":"Carson was coming off a 55-goal season at age 20, but the Canadian public viewed the trade as national betrayal.","consensusVerdictAtTime":"Cultural earthquake. Edmonton received elite young pieces and massive cash, but traded away the greatest player on earth.","cupOddsDeltaTeamA":"+60% (Instantly elevated Kings to contenders)","cupOddsDeltaTeamB":"-25% (Oilers still loaded with Messier, Kurri, Anderson)","players":[{"name":"Wayne Gretzky","team":"LAK","ageAtTrade":27,"seasonPriorStats":"64 GP | 40 G | 109 A | 149 PTS (4x Stanley Cup Champ)","contractStatus":"1 year remaining, signed new long-term deal in LA","perceivedValue":"The undisputed greatest player of all time in his absolute prime."},{"name":"Jimmy Carson","team":"EDM","ageAtTrade":20,"seasonPriorStats":"80 GP | 55 G | 52 A | 107 PTS","contractStatus":"Rising young star","perceivedValue":"One of the best young American goal scorers in NHL history."}]}', '{"verdictToday":"Transformative for the entire sport of hockey. Gretzky led LA to the 1993 Finals and revolutionized US hockey broadcasting. Remarkably, Edmonton still won the 1990 Stanley Cup without Gretzky behind Mark Messier.","lopsidednessRating":"EVEN_WIN_WIN","winningTeam":"Los Angeles Kings / The Sport of Hockey","teamASuccessSummary":"Gretzky won 1989 Hart Trophy, led Kings to 1993 Stanley Cup Final, shattered NHL all-time scoring records in an LA sweater.","teamBSuccessSummary":"Won the 1990 Stanley Cup (cementing Oilers dynasty); however, Carson demanded a trade out of Edmonton after just 84 games due to pressure.","championshipImpact":"Edmonton won 1990 Stanley Cup without Gretzky; Kings reached 1993 Stanley Cup Final.","milestones":[{"year":"1989","title":"Gretzky Wins Hart in LA","description":"Gretzky scores 168 points in his first season in LA, winning the Hart Trophy and eliminating Edmonton in the playoffs.","tag":"AWARD"},{"year":"1990","title":"Oilers Win 1990 Cup Without Gretzky","description":"Led by Mark Messier and Bill Ranford, Edmonton claims their 5th Stanley Cup in 7 years.","tag":"CHAMPIONSHIP"},{"year":"1993","title":"Kings Reach 1993 Stanley Cup Final","description":"Gretzky scores unforgettable hat trick in Game 7 of Campbell Conference Final vs Toronto to push Kings into the Finals.","tag":"CHAMPIONSHIP"}],"tradeTreeEvents":[{"team":"EDM","year":"1989","event":"Carson Demands Trade to Detroit","details":"Unable to endure the pressure of replacing Gretzky, Carson sits out and is traded to Detroit for Petr Klima, Joe Murphy, and Adam Graves.","result":"Klima and Graves score huge goals to win the 1990 Stanley Cup for Edmonton."}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, historical_outcome=excluded.historical_outcome;
INSERT INTO historical_trades (id, date, season_era, title, description, trade_tree_description, team_a, team_b, initial_perspective, historical_outcome) VALUES ('oreilly-blues-2018', 'July 1, 2018', 'Salary Cap Era (2010s)', 'The Ryan O''Reilly Conn Smythe Trade', 'Buffalo Sabres trade Ryan O''Reilly to St. Louis Blues for Patrik Berglund, Vladimir Sobotka, Tage Thompson, a 2019 1st (Ryan Johnson), and a 2021 2nd.', 'St. Louis found their missing 1C and won their first-ever Stanley Cup within 11 months, while Buffalo eventually saw Tage Thompson evolve into an offensive juggernaut.', '{"teamName":"St. Louis Blues","teamAbbrev":"STL","teamLogo":"https://assets.nhle.com/logos/nhl/svg/STL_light.svg","gaveUp":["Patrik Berglund","Vladimir Sobotka","Tage Thompson","2019 1st","2021 2nd"],"received":["Ryan O''Reilly"],"snapshotGrade":"A","retrospectiveGrade":"A+"}', '{"teamName":"Buffalo Sabres","teamAbbrev":"BUF","teamLogo":"https://assets.nhle.com/logos/nhl/svg/BUF_light.svg","gaveUp":["Ryan O''Reilly"],"received":["Patrik Berglund","Vladimir Sobotka","Tage Thompson","2019 1st","2021 2nd"],"snapshotGrade":"B-","retrospectiveGrade":"B+"}', '{"narrative":"O''Reilly candidly stated after the 2017-18 season that Buffalo''s losing culture had caused him to \"lose my love for the game at multiple times.\" Buffalo felt forced to move him before his $7.5M bonus was paid.","teamAOutlook":"St. Louis added a premier Selke-caliber center to complement Tarasenko and Pietrangelo.","teamBOutlook":"Buffalo aimed to diversify their depth with veterans and young 6''6\" prospect Tage Thompson.","consensusVerdictAtTime":"Clear win for St. Louis getting the best player in the deal.","cupOddsDeltaTeamA":"+22% (Solidified center spine)","cupOddsDeltaTeamB":"-15% (Loss of elite defensive pivot)","players":[{"name":"Ryan O''Reilly","team":"STL","ageAtTrade":27,"seasonPriorStats":"81 GP | 24 G | 37 A | 61 PTS | 60.0% Faceoff Win","contractStatus":"5 years remaining at $7.5M AAV","perceivedValue":"Elite two-way Selke-caliber center."},{"name":"Tage Thompson","team":"BUF","ageAtTrade":20,"seasonPriorStats":"41 GP | 3 G | 6 A | 9 PTS","contractStatus":"Entry-Level Contract","perceivedValue":"Raw 6''6\" winger prospect with powerful shot."}]}', '{"verdictToday":"A monumental immediate win for St. Louis, winning the 2019 Stanley Cup and Conn Smythe. However, Buffalo eventually salvaged massive long-term value when Tage Thompson transitioned to center and exploded for 47 goals in 2022-23.","lopsidednessRating":"DECISIVE_WIN","winningTeam":"St. Louis Blues (Short-term Cup) & Buffalo Sabres (Long-term Tage)","teamASuccessSummary":"O''Reilly won the 2019 Conn Smythe Trophy, Selke Trophy, and 2019 Stanley Cup in year 1.","teamBSuccessSummary":"Berglund and Sobotka quickly washed out, but Tage Thompson blossomed into an elite 47-goal, 94-point franchise center.","championshipImpact":"2019 Stanley Cup Champions (St. Louis Blues).","milestones":[{"year":"2019","title":"2019 Stanley Cup & Conn Smythe","description":"O''Reilly scores in 4 consecutive Stanley Cup Final games, winning the Conn Smythe and delivering St. Louis'' first Cup.","tag":"CHAMPIONSHIP"},{"year":"2023","title":"Tage Thompson Explodes for 47 Goals","description":"Thompson finishes 2022-23 with 47 goals and 94 points, scoring 5 goals in a single game vs Columbus.","tag":"AWARD"}],"tradeTreeEvents":[{"team":"STL","year":"2023","event":"O''Reilly Traded to Toronto","details":"Blues trade pending UFA O''Reilly to Maple Leafs at deadline for a 2023 1st round pick.","result":"St. Louis recoups 1st round draft asset."}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, historical_outcome=excluded.historical_outcome;
